head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vListProcsStatCd = "";
scwin.vListBzDtlTpCd = "";
scwin.procsNo;
scwin.gRegEmpNo;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        const parentWin = $c.frame.path("../");
        // var parentYn = parentWin.procsNo;

        getProcsNo = parentWin.fn_getProcsNo;
        scwin.procsNo = getProcsNo();
        scwin.vListBzDtlTpCd = parentWin.clickListBzDtlTpCd;
        scwin.vListProcsStatCd = parentWin.clickListProcsStatCd;
        await scwin.read();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07061.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name trs_Read_OnFail
 * @description Read On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Read_OnFail = async function() {
    try {
        await $c.win.alert(trs_Read.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07061.trs_Read_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A001", "승인"));
        scwin.parentRefresh();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07061.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "승인"));
        await $c.win.alert(trs_Save.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07061.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name dts_ContentsInfo_OnLoadError
 * @description dts_ContentsInfo 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ContentsInfo_OnLoadError = async function() {
    try {
        await $c.win.alert('dts_ContentsInfo.OnLoadError()');
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07061.dts_ContentsInfo_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ContentsInfo_OnLoadCompleted
 * @description dts_ContentsInfo 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ContentsInfo_OnLoadCompleted = function(rowcount) {
    try {
        if ("32" !== scwin.vListProcsStatCd) {
            btn_save.setBackgroundImage("../img/btn_approval_d.gif");
            btn_save.setDisabled(true);
            btn_delete.setBackgroundImage("../img/btn_reject_d.gif");
            btn_delete.setDisabled(true);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07061.dts_ContentsInfo_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_Report_OnLoadError
 * @description dts_Report 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Report_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Report);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07061.dts_Report_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_save_onclick
 * @description 「저장」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function() {
    try {
        let rtn = confirm('승인 하시겠습니까?');
        if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

        {
            await scwin.save("33");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07061.btn_save_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 「반려」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_delete_onclick = async function() {
    try {
        let rtn = confirm('반려 하시겠습니까?');
        if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

        {
            await scwin.save("37");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07061.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_cancel_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07061.btn_cancel_onclick" });
    }
};

/**
 * @method
 * @name trs_Read_OnFail
 * @description Read On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Read_OnFail = async function() {
    try {
        await $c.win.alert(trs_Read.ErrorMsg);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07061.trs_Read_OnFail" });
    }
};

/**
 * @method
 * @name btn_Print_onclick
 * @description 「인쇄」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Print_onclick = function() {
    try {
        scwin.print();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07061.btn_Print_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name read
 * @description read 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.read = async function() {
    const sbmOptions = {
        id : "sbm_trs_Read",
        action : "/lstinvstg/ListFee.do",
        ref : "dts_ContentsInfo",
        target : "trs_Read=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name save
 * @description save 처리
 * @param {String} listProcsStatCd listProcsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function(listProcsStatCd) {
    scwin.setHeader();
    dts_ProcData.insertRow();
    dts_ProcData.setCellData(1, "BZ_PROCS_NO", scwin.procsNo);
    dts_ProcData.setCellData(1, "LIST_BZ_DTL_TP_CD", scwin.vListBzDtlTpCd);
    dts_ProcData.setCellData(1, "LIST_PROCS_STAT_CD", listProcsStatCd);
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/lstinvstg/ListFee.do",
        ref : "dts_ProcData",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {void}
 * @hidden N
 */
scwin.setHeader = function() {
    dts_ProcData.removeAll();
    // dts_ProcData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {void}
 * @hidden N
 */
scwin.print = function() {
    let arrAmt = ["", "", "", "", "", "", "", "", ""];
    let payAmt = dts_ContentsInfo.getCellData(1, "PAY_AMT");
    let len = payAmt.length;
    for (let i = 0; i < payAmt.length; i++) {
        arrAmt[i] = payAmt.substring((len - (i + 1)), len - i);
    }
    const userParam = [{
        uid: "comNm",
        unm: dts_ContentsInfo.getCellData(1, "ISUR_NM")
    }, {
        uid: "lstPayAmt1",
        unm: arrAmt[0]
    }, {
        uid: "lstPayAmt2",
        unm: arrAmt[1]
    }, {
        uid: "lstPayAmt3",
        unm: arrAmt[2]
    }, {
        uid: "lstPayAmt4",
        unm: arrAmt[3]
    }, {
        uid: "lstPayAmt5",
        unm: arrAmt[4]
    }, {
        uid: "lstPayAmt6",
        unm: arrAmt[5]
    }, {
        uid: "lstPayAmt7",
        unm: arrAmt[6]
    }, {
        uid: "lstPayAmt8",
        unm: arrAmt[7]
    }, {
        uid: "lstPayAmt9",
        unm: arrAmt[8]
    }, {
        uid: "feeNm",
        unm: dts_ContentsInfo.getCellData(1, "LIST_FEE_ANULFEE_TP_NM")
    }, {
        uid: "printDate2",
        unm: $c.ut.cGetToday("yyyy-mm-dd")
    }];
    const pdf_rptname = "RLDSTF00034";
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};

/**
 * @method
 * @name printOld
 * @description print Old 처리
 * @returns {void}
 * @hidden N
 */
scwin.printOld = function() {

    // dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    let arrAmt = ["", "", "", "", "", "", "", "", ""];
    let payAmt = dts_ContentsInfo.getCellData(1, "PAY_AMT");
    let len = payAmt.length;
    for (let i = 0; i < payAmt.length; i++) {
        arrAmt[i] = payAmt.substring((len - (i + 1)), len - i);
    }
    dts_Print.insertRow();
    dts_Print.setCellData(1, "comNm", dts_ContentsInfo.getCellData(1, "ISUR_NM"));
    dts_Print.setCellData(1, "lstPayAmt1", arrAmt[0]);
    dts_Print.setCellData(1, "lstPayAmt2", arrAmt[1]);
    dts_Print.setCellData(1, "lstPayAmt3", arrAmt[2]);
    dts_Print.setCellData(1, "lstPayAmt4", arrAmt[3]);
    dts_Print.setCellData(1, "lstPayAmt5", arrAmt[4]);
    dts_Print.setCellData(1, "lstPayAmt6", arrAmt[5]);
    dts_Print.setCellData(1, "lstPayAmt7", arrAmt[6]);
    dts_Print.setCellData(1, "lstPayAmt8", arrAmt[7]);
    dts_Print.setCellData(1, "lstPayAmt9", arrAmt[8]);
    dts_Print.setCellData(1, "feeNm", dts_ContentsInfo.getCellData(1, "LIST_FEE_ANULFEE_TP_NM"));
    const testDateSet = rex_gfGetGauceCsvStr(dts_Print);
    const rex_rptname = "RLDFIL00034";
    $c.rpt.fn_open_report(testDateSet, rex_rptname, dts_ContentsInfo);
};

/**
 * @method
 * @name parentRefresh
 * @description parent Refresh 처리
 * @returns {void}
 * @hidden N
 */
scwin.parentRefresh = function() {
    const fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};
